import { google } from 'googleapis';

export async function getSheetsData() {
    try {
        const auth = new google.auth.GoogleAuth({
            credentials: {
                client_email: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL,
                private_key: process.env.GOOGLE_PRIVATE_KEY?.replace(/\\n/g, '\n'),
            },
            scopes: ['https://www.googleapis.com/auth/spreadsheets.readonly'],
        });

        const sheets = google.sheets({ version: 'v4', auth });
        const spreadsheetId = process.env.GOOGLE_SHEETS_SPREADSHEET_ID;

        // 1. Detectar o nome correto da aba de lançamento
        const meta = await sheets.spreadsheets.get({ spreadsheetId });
        const launchSheet = meta.data.sheets?.find(s =>
            s.properties?.title?.toLowerCase().includes('lancamento') ||
            s.properties?.title?.toLowerCase().includes('lançamento')
        );

        const sheetName = launchSheet?.properties?.title || '01_Lancamento_Dados';

        // 2. Ler os dados usando o nome detectado
        const response = await sheets.spreadsheets.values.get({
            spreadsheetId,
            range: `'${sheetName}'!A1:Z500`,
        });

        const rows = response.data.values;
        if (!rows || rows.length === 0) {
            return [];
        }

        // Converter as linhas em objetos usando o header
        const headers = rows[0];
        const data = rows.slice(1).map(row => {
            const obj: any = {};
            headers.forEach((header, index) => {
                obj[header] = row[index] || '';
            });
            return obj;
        });

        return data;
    } catch (error) {
        console.error('Erro ao buscar dados do Google Sheets:', error);
        return null;
    }
}
